update abr_product
set product_name = #{productName}, category = #{category}, degrees = cast(#{degrees} as jsonb), countries = cast(#{countries} as jsonb),
    description = coalesce(#{description}, ''), price_min = #{priceMin}, price_max = #{priceMax}, currency = coalesce(#{currency}, 'CNY'),
    price_note = coalesce(#{priceNote}, ''), bookable = #{bookable}, duration_minutes = #{durationMinutes}, sort_order = coalesce(#{sortOrder}, 0),
    status = #{status}, update_by = #{updateBy}, update_time = now(), remark = #{remark}
where product_id = #{productId}
